package org.apache.commons.io.monitor;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.attribute.FileTime;

import org.apache.commons.io.FileUtils;
import org.apache.commons.io.file.attribute.FileTimes;

/**
 * Package-level helper encapsulating file metadata and refresh logic.
 */
class FileAttributes {

    String name;
    boolean exists;
    boolean directory;
    SerializableFileTime lastModified = SerializableFileTime.EPOCH;
    long length;

    FileAttributes(final File file) {
        // initialize from the provided file
        this.name = file.getName();
        this.exists = Files.exists(file.toPath());
        this.directory = exists && file.isDirectory();
        try {
            setLastModified(exists ? FileUtils.lastModifiedFileTime(file) : FileTimes.EPOCH);
        } catch (final IOException e) {
            setLastModified(SerializableFileTime.EPOCH);
        }
        this.length = exists && !directory ? file.length() : 0;
    }

    String getName() {
        return name;
    }

    long getLastModified() {
        return lastModified.toMillis();
    }

    FileTime getLastModifiedFileTime() {
        return lastModified.unwrap();
    }

    long getLength() {
        return length;
    }

    boolean isDirectory() {
        return directory;
    }

    boolean isExists() {
        return exists;
    }

    void setName(final String name) {
        this.name = name;
    }

    void setExists(final boolean exists) {
        this.exists = exists;
    }

    void setDirectory(final boolean directory) {
        this.directory = directory;
    }

    void setLength(final long length) {
        this.length = length;
    }

    void setLastModified(final FileTime lastModified) {
        setLastModified(new SerializableFileTime(lastModified));
    }

    void setLastModified(final long lastModified) {
        setLastModified(FileTime.fromMillis(lastModified));
    }

    void setLastModified(final SerializableFileTime lastModified) {
        this.lastModified = lastModified;
    }

    /**
     * Refreshes the attributes from the {@link File}, indicating whether the file has changed.
     * Returns true if any of exists, lastModified, directory or length changed.
     */
    boolean refresh(final File file) {
        final boolean origExists = exists;
        final SerializableFileTime origLastModified = lastModified;
        final boolean origDirectory = directory;
        final long origLength = length;

        name = file.getName();
        exists = Files.exists(file.toPath());
        directory = exists && file.isDirectory();
        try {
            setLastModified(exists ? FileUtils.lastModifiedFileTime(file) : FileTimes.EPOCH);
        } catch (final IOException e) {
            setLastModified(SerializableFileTime.EPOCH);
        }
        length = exists && !directory ? file.length() : 0;

        return exists != origExists || !lastModified.equals(origLastModified) || directory != origDirectory
            || length != origLength;
    }
}
